import { Group } from '@visx/group';
import React from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';

import {
  INACTIVE_SEGMENT_VALUE,
  HIGHLIGHTED_SEGMENT_VALUE,
} from './types/default.js';
import { useMeterBarLayoutSize } from '../../context/MeterBarLayoutSize.context.js';
import { getChartElementsSizes } from '../../functions/get-chart-elements-sizes.js';
import { DEFAULT_GAP_WIDTH } from '../../types/default.js';

interface MeterBarSegmentProps {
  color: string;
  width: number;
  highlighted?: boolean;
  start?: number;
  onClickAction?: (event: React.MouseEvent) => void;
  onMouseEnterAction?: (event: React.MouseEvent) => void;
  onMouseLeaveAction?: (event: React.MouseEvent) => void;
  onMouseMoveAction?: (event: React.MouseEvent) => void;
}

export const MeterBarSegment = (props: MeterBarSegmentProps) => {
  const {
    color,
    width,
    highlighted = true,
    start = 0,
    onClickAction,
    onMouseEnterAction,
    onMouseLeaveAction,
    onMouseMoveAction,
  } = props;

  const { size } = useMeterBarLayoutSize();
  const { chartHeight } = getChartElementsSizes(size);

  return (
    <Group
      onMouseEnter={onMouseEnterAction}
      onMouseLeave={onMouseLeaveAction}
      onMouseMove={onMouseMoveAction}
      onClick={onClickAction}
    >
      <rect
        x={start}
        y="0"
        width={width}
        height={chartHeight}
        fill={color}
        opacity={
          highlighted ? HIGHLIGHTED_SEGMENT_VALUE : INACTIVE_SEGMENT_VALUE
        }
        data-testid="meterbar-segment"
        stroke={Colors.Background.Base.Default}
        strokeWidth={DEFAULT_GAP_WIDTH}
        strokeDasharray={`0, ${width}, ${chartHeight}, ${width + chartHeight}`}
      />
    </Group>
  );
};
